/** Array of panel names rendered in the page component. */
export declare const pagePanels: readonly ["sidebar", "main", "details"];
/** Panels rendered in the page component. */
export type PagePanels = (typeof pagePanels)[number];
/** Page panels that can be dismissed. */
export type DismissiblePagePanels = Extract<PagePanels, 'sidebar' | 'details'>;
/** Object holding the current widths of the panels rendered in the page. */
export type SlotWidths = {
    [key in PagePanels]?: number;
};
/** Current size of each page panel in different units. */
export type PagePanelSizes = Record<PagePanels, {
    [key in 'px' | '%']: number;
}>;
export type ControlledPagePanelProps = {
    /** If the panel is opened. */
    dismissed: boolean;
    /** If the panel is dismissed by default. */
    defaultDismissed?: never;
};
export type UncontrolledPagePanelProps = {
    /** If the panel is opened. */
    dismissed?: never;
    /** If the panel is dismissed by default. */
    defaultDismissed?: boolean;
};
export type PagePanelProps = ControlledPagePanelProps | UncontrolledPagePanelProps;
